1	export type Item = {
2	  type: string;
3	  material?: string;
4	  enchantment?: number;
5	  cursed?: boolean;
6	};
7	
8	export type Damage = {
9	  itemType: string;
10	  amount: number;
11	};
12	
13	export type Step =
14	  | { op: "quote"; items: Item[] }
15	  | { op: "claim"; policy: number; incident: { cause: string; damages: Damage[] } };
16	
17	export type Customer = { yearsWithMHPCO: number };
18	
19	export type Scenario = {
20	  customer: Customer;
21	  steps: Step[];
22	};
23	
24	export type Result = { premium: number } | { payout: number; remainingCap: number };
25	
26	const PROCESSING_FEE = 5;
27	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
28	const CURSE_SURCHARGE_RATE = 0.5;
29	const HIGH_ENCHANTMENT_THRESHOLD = 5;
30	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
31	const LOYALTY_YEARS_THRESHOLD = 2;
32	const LOYALTY_DISCOUNT_RATE = 0.2;
33	const FOLLOW_UP_DISCOUNT_RATE = 0.15;
34	
35	const BASE_PREMIUMS: Record<string, number> = {
36	  sword: 100,
37	  amulet: 60,
38	  staff: 80,
39	  potion: 40,
40	  rune: 25,
41	  moonstone: 25,
42	};
43	
44	const INSURANCE_VALUES: Record<string, number> = {
45	  sword: 1000,
46	  amulet: 600,
47	  staff: 800,
48	  potion: 400,
49	  rune: 250,
50	  moonstone: 250,
51	};
52	
53	const DEDUCTIBLE_PER_DAMAGE = 100;
54	const HALF_REIMBURSEMENT_ENCHANTMENT_THRESHOLD = 8;
55	const HALF_REIMBURSEMENT_RATE = 0.5;
56	const CAP_MULTIPLE_OF_INSURANCE_SUM = 2;
57	
58	const BLOCK_SIZE = 3;
59	const BLOCK_PREMIUM = 60;
60	
61	/** Items that share the same `type`, and so are priced together. */
62	type AlikeItems = Item[];
63	
64	const groupAlikeItems = (items: Item[]): AlikeItems[] => {
65	  const byType = new Map<string, AlikeItems>();
66	  items.forEach((item) => byType.set(item.type, [...(byType.get(item.type) ?? []), item]));
67	  return [...byType.values()];
68	};
69	
70	const formsBlock = (items: AlikeItems): boolean => items.length === BLOCK_SIZE;
71	
72	const itemBasePremium = (item: Item): number => BASE_PREMIUMS[item.type];
73	
74	const alikeItemsBasePremium = (alikeItems: AlikeItems): number =>
75	  formsBlock(alikeItems)
76	    ? BLOCK_PREMIUM
77	    : alikeItems.reduce((total, item) => total + itemBasePremium(item), 0);
78	
79	const totalBasePremium = (items: Item[]): number =>
80	  groupAlikeItems(items).reduce((total, alikeItems) => total + alikeItemsBasePremium(alikeItems), 0);
81	
82	const isCursed = (item: Item): boolean => item.cursed === true;
83	
84	const isHighlyEnchanted = (item: Item): boolean =>
85	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD;
86	
87	/**
88	 * An additive rate rule: contributes `rate` × some base premium, but only to
89	 * subjects the rule `applies` to. Every rule is an independent additive term —
90	 * nothing compounds onto a running total — so a discount is simply a negative
91	 * `rate` rather than a subtraction applied at some point in a sequence.
92	 */
93	type RateRule<Subject> = { applies: (subject: Subject) => boolean; rate: number };
94	
95	/**
96	 * The combined rate of every rule that applies to `subject`. Callers multiply
97	 * this by the relevant base premium once, which keeps each rule additive.
98	 */
99	const combinedRate = <Subject>(rules: RateRule<Subject>[], subject: Subject): number =>
100	  rules.filter(({ applies }) => applies(subject)).reduce((total, { rate }) => total + rate, 0);
101	
102	const ITEM_SURCHARGES: RateRule<Item>[] = [
103	  { applies: isCursed, rate: CURSE_SURCHARGE_RATE },
104	  { applies: isHighlyEnchanted, rate: HIGH_ENCHANTMENT_SURCHARGE_RATE },
105	];
106	
107	const itemSurcharge = (item: Item): number =>
108	  itemBasePremium(item) * combinedRate(ITEM_SURCHARGES, item);
109	
110	/**
111	 * Summed across the policy's items, but each term is charged on the item's own
112	 * base premium — so this is item-scoped pricing that merely totals up, unlike
113	 * `policyAdjustments`, which rates the policy base as a whole.
114	 */
115	const itemSurchargesTotal = (items: Item[]): number =>
116	  items.reduce((total, item) => total + itemSurcharge(item), 0);
117	
118	/** Everything a policy-wide rule may look at when deciding whether it applies. */
119	type Policy = { customer: Customer; priorContracts: number };
120	
121	const isLoyalCustomer = ({ customer }: Policy): boolean =>
122	  customer.yearsWithMHPCO >= LOYALTY_YEARS_THRESHOLD;
123	
124	const isFollowUpContract = ({ priorContracts }: Policy): boolean => priorContracts > 0;
125	
126	/**
127	 * Charged once per quote on the policy's base premium.
128	 *
129	 * The unconditional first-insurance surcharge is deliberately not in this table:
130	 * see `FIRST_INSURANCE_SURCHARGE_RATE` at the quote site.
131	 */
132	const POLICY_ADJUSTMENTS: RateRule<Policy>[] = [
133	  { applies: isLoyalCustomer, rate: -LOYALTY_DISCOUNT_RATE },
134	  { applies: isFollowUpContract, rate: -FOLLOW_UP_DISCOUNT_RATE },
135	];
136	
137	const policyAdjustments = (policyBasePremium: number, policy: Policy): number =>
138	  policyBasePremium * combinedRate(POLICY_ADJUSTMENTS, policy);
139	
140	const quotePremium = (items: Item[], policy: Policy): number => {
141	  const policyBasePremium = totalBasePremium(items);
142	  // The first-insurance surcharge has no condition to test: the MHPCO treats
143	  // every item in a quote as newly insured, so it is charged on every quote,
144	  // including a long-standing customer's follow-up contract. That makes it a
145	  // fixed rate on the base — like PROCESSING_FEE is a fixed addend — rather
146	  // than a rule belonging in POLICY_ADJUSTMENTS.
147	  const firstInsuranceSurcharge = policyBasePremium * FIRST_INSURANCE_SURCHARGE_RATE;
148	  // Every term is added to the base, never multiplied onto a running total. The
149	  // algebraically equivalent base * (1 + rate) yields 110.00000000000001 for
150	  // base 100, which Math.ceil turns into a premium that is 1 G too high.
151	  return Math.ceil(
152	    policyBasePremium +
153	      itemSurchargesTotal(items) +
154	      firstInsuranceSurcharge +
155	      policyAdjustments(policyBasePremium, policy) +
156	      PROCESSING_FEE,
157	  );
158	};
159	
160	const isQuote = (step: Step): boolean => step.op === "quote";
161	
162	/**
163	 * A contract is created by each quote, so the number the customer already held
164	 * when `stepIndex` is reached is just the number of quotes before it. Claims are
165	 * not contracts and so do not count.
166	 */
167	const priorContractsAt = (steps: Step[], stepIndex: number): number =>
168	  steps.slice(0, stepIndex).filter(isQuote).length;
169	
170	const insuredItems = (steps: Step[], policyIndex: number): Item[] => {
171	  const step = steps[policyIndex];
172	  if (step?.op !== "quote") throw new Error(`Step ${policyIndex} did not create a policy`);
173	  return step.items;
174	};
175	
176	/**
177	 * The insured item a damage entry refers to. Matching is by `itemType` only —
178	 * a damage entry names a type, not a specific item, so with several alike items
179	 * on one policy the first match stands in for whichever was damaged.
180	 */
181	const damagedItem = (insured: Item[], damage: Damage): Item => {
182	  const item = insured.find(({ type }) => type === damage.itemType);
183	  if (!item) throw new Error(`Policy does not cover an item of type ${damage.itemType}`);
184	  return item;
185	};
186	
187	const insuranceSum = (items: Item[]): number =>
188	  items.reduce((total, item) => total + INSURANCE_VALUES[item.type], 0);
189	
190	/**
191	 * The reimbursable value of a damage before the deductible. Special clauses key
192	 * off the DAMAGED ITEM's own properties, so this takes the insured item rather
193	 * than the damage entry alone.
194	 *
195	 * The spec's dragon-material clause has no branch here on purpose: full
196	 * reimbursement is already the no-clause baseline, and where dragon material
197	 * meets enchantment >= 8 the 50 % rule wins, so a `material === "dragon"`
198	 * branch could only return what these two lines already return.
199	 */
200	const reimbursedAmount = (damage: Damage, insuredItem: Item): number =>
201	  (insuredItem.enchantment ?? 0) >= HALF_REIMBURSEMENT_ENCHANTMENT_THRESHOLD
202	    ? damage.amount * HALF_REIMBURSEMENT_RATE
203	    : damage.amount;
204	
205	/** The deductible is charged per damaged item, not once per incident. */
206	const damagePayout = (damage: Damage, insuredItem: Item): number =>
207	  reimbursedAmount(damage, insuredItem) - DEDUCTIBLE_PER_DAMAGE;
208	
209	const incidentPayout = (damages: Damage[], insured: Item[]): number =>
210	  // Rounded down, in the MHPCO's favor. Applied to the incident total rather
211	  // than to each damage, so a single incident loses at most 1 G to rounding.
212	  Math.floor(
213	    damages.reduce((total, damage) => total + damagePayout(damage, damagedItem(insured, damage)), 0),
214	  );
215	
216	/** A policy pays out at most twice the insurance sum of the items it covers. */
217	const payoutCap = (items: Item[]): number => insuranceSum(items) * CAP_MULTIPLE_OF_INSURANCE_SUM;
218	
219	/**
220	 * What the policy can still pay after `paidOut` has been paid against it.
221	 *
222	 * `paidOut` is the total ever paid on the policy, not one claim's payout: the
223	 * cap belongs to the policy and is consumed by every claim made against it. No
224	 * test yet makes a second claim on one policy, so the only caller passes a
225	 * single claim's payout — naming the concept keeps that assumption visible here
226	 * rather than buried in arithmetic at the call site.
227	 */
228	const remainingCap = (insured: Item[], paidOut: number): number => payoutCap(insured) - paidOut;
229	
230	const claimResult = (steps: Step[], policyIndex: number, damages: Damage[]) => {
231	  const insured = insuredItems(steps, policyIndex);
232	  const payout = incidentPayout(damages, insured);
233	  return { payout, remainingCap: remainingCap(insured, payout) };
234	};
235	
236	export const runScenario = (scenario: Scenario): Result[] =>
237	  scenario.steps.map((step, stepIndex) => {
238	    if (step.op === "quote") {
239	      const policy = {
240	        customer: scenario.customer,
241	        priorContracts: priorContractsAt(scenario.steps, stepIndex),
242	      };
243	      return { premium: quotePremium(step.items, policy) };
244	    }
245	    return claimResult(scenario.steps, step.policy, step.incident.damages);
246	  });
