const claimResult = (steps: Step[], policyIndex: number, damages: Damage[]) => {
  // The same list serves two different scopes: the payout looks up only the
  // damaged items within it, while the cap is drawn from all of it.
  const policyItems = insuredItems(steps, policyIndex);
  const payout = incidentPayout(damages, policyItems);
  return { payout, remainingCap: remainingCap(policyItems, payout) };
};
